-- =========================================================
-- 0001_init.sql: FeastFlow source schema (M1)
--
-- Conventions:
--   * Ids: BIGINT identity, generated by Postgres.
--   * Money: INTEGER paise (Debezium sends numeric as base64 bytes).
--   * Times: TIMESTAMPTZ (Debezium sends an ISO-8601 UTC string).
--   * Statuses: TEXT + CHECK (easier to evolve than ENUM types).
--   * Every table has created_at / updated_at; a trigger keeps
--     updated_at current on UPDATE.
--
-- Delete policy (what the generator may really DELETE):
--   * customers, riders: never hard-deleted once referenced;
--     anonymize personal fields instead.
--   * menu_items: soft-deleted via is_available = FALSE once sold.
--   * orders: abandoned PLACED orders may be purged; their
--     order_items go with them (ON DELETE CASCADE).
-- =========================================================


-- ---------------------------------------------------------
-- 1. CUSTOMERS
-- ---------------------------------------------------------
CREATE TABLE customers (
    customer_id  BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name         TEXT NOT NULL,
    email        TEXT UNIQUE,                 -- optional; several NULLs allowed
    phone        TEXT NOT NULL UNIQUE,
    address      TEXT NOT NULL,
    city         TEXT NOT NULL
                 CHECK (city IN ('Hyderabad', 'Bengaluru')),
    zip          TEXT CHECK (zip ~ '^[0-9]{6}$'),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------
-- 2. RESTAURANTS
-- ---------------------------------------------------------
CREATE TABLE restaurants (
    restaurant_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name          TEXT NOT NULL,
    address       TEXT NOT NULL,
    phone         TEXT NOT NULL UNIQUE,
    city          TEXT NOT NULL
                  CHECK (city IN ('Hyderabad', 'Bengaluru')),
    zip           TEXT CHECK (zip ~ '^[0-9]{6}$'),
    -- NULL = not rated yet. Kept NUMERIC: the Debezium connector
    -- must set decimal.handling.mode=string (step 5).
    rating        NUMERIC(2,1)
                  CHECK (rating BETWEEN 0 AND 5),
    -- Time of day. closes_at < opens_at means open past midnight.
    opens_at      TIME NOT NULL,
    closes_at     TIME NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------
-- 3. RIDERS
-- ---------------------------------------------------------
CREATE TABLE riders (
    rider_id     BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name         TEXT NOT NULL,
    email        TEXT UNIQUE,
    phone        TEXT NOT NULL UNIQUE,
    address      TEXT NOT NULL,
    city         TEXT NOT NULL
                 CHECK (city IN ('Hyderabad', 'Bengaluru')),
    zip          TEXT CHECK (zip ~ '^[0-9]{6}$'),
    status       TEXT NOT NULL DEFAULT 'OFFLINE'
                 CHECK (status IN ('AVAILABLE', 'OFFLINE', 'ON_DELIVERY')),
    -- NULL = not rated yet (see restaurants.rating for the CDC note).
    rating       NUMERIC(2,1)
                 CHECK (rating BETWEEN 0 AND 5),
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------
-- 4. MENU ITEMS
-- ---------------------------------------------------------
CREATE TABLE menu_items (
    item_id       BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    -- A restaurant that still has menu items cannot be hard-deleted.
    restaurant_id BIGINT NOT NULL
                  REFERENCES restaurants (restaurant_id)
                  ON DELETE RESTRICT,
    name          TEXT NOT NULL,
    description   TEXT,
    price_paise   INTEGER NOT NULL CHECK (price_paise > 0),
    -- Soft delete: items that were ever sold stay in the table and
    -- leave the menu by setting is_available = FALSE.
    is_available  BOOLEAN NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------
-- 5. ORDERS
-- ---------------------------------------------------------
CREATE TABLE orders (
    order_id      BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    -- Customers with orders are anonymized, never hard-deleted.
    customer_id   BIGINT NOT NULL
                  REFERENCES customers (customer_id)
                  ON DELETE RESTRICT,
    -- Restaurants referenced by order history are kept.
    restaurant_id BIGINT NOT NULL
                  REFERENCES restaurants (restaurant_id)
                  ON DELETE RESTRICT,
    -- NULL until a rider accepts. Riders with delivery history are
    -- anonymized, never deleted, so rider metrics (M3) stay intact.
    rider_id      BIGINT
                  REFERENCES riders (rider_id)
                  ON DELETE RESTRICT,
    total_paise   INTEGER NOT NULL CHECK (total_paise > 0),
    status        TEXT NOT NULL DEFAULT 'PLACED'
                  CHECK (status IN ('PLACED', 'ACCEPTED', 'PREPARING',
                                    'PICKED_UP', 'DELIVERED', 'CANCELLED')),
    -- Lifecycle timestamps: M3 delivery SLAs and M4 ETA features.
    placed_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    accepted_at   TIMESTAMPTZ,
    picked_up_at  TIMESTAMPTZ,
    delivered_at  TIMESTAMPTZ,
    cancelled_at  TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------
-- 6. ORDER ITEMS
-- ---------------------------------------------------------
CREATE TABLE order_items (
    order_item_id    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    -- Purging an abandoned order deletes its lines too. Each cascaded
    -- delete is a real WAL change, so CDC emits one event per line.
    order_id         BIGINT NOT NULL
                     REFERENCES orders (order_id)
                     ON DELETE CASCADE,
    -- Sold menu items cannot be hard-deleted (soft delete instead).
    item_id          BIGINT NOT NULL
                     REFERENCES menu_items (item_id)
                     ON DELETE RESTRICT,
    quantity         INTEGER NOT NULL CHECK (quantity > 0),
    -- Price at the moment of the order; menu prices may change later.
    unit_price_paise INTEGER NOT NULL CHECK (unit_price_paise > 0),
    discount_paise   INTEGER NOT NULL DEFAULT 0 CHECK (discount_paise >= 0),
    tax_paise        INTEGER NOT NULL DEFAULT 0 CHECK (tax_paise >= 0),
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------
-- 7. FOREIGN KEY INDEXES
-- Postgres indexes the parent side (the primary key) but not the
-- child side of a foreign key.
-- ---------------------------------------------------------
CREATE INDEX idx_menu_items_restaurant_id ON menu_items (restaurant_id);
CREATE INDEX idx_orders_customer_id       ON orders (customer_id);
CREATE INDEX idx_orders_restaurant_id     ON orders (restaurant_id);
CREATE INDEX idx_orders_rider_id          ON orders (rider_id);
CREATE INDEX idx_order_items_order_id     ON order_items (order_id);
CREATE INDEX idx_order_items_item_id      ON order_items (item_id);


-- ---------------------------------------------------------
-- 8. updated_at TRIGGER FUNCTION
-- now() is the transaction start time.
-- ---------------------------------------------------------
CREATE FUNCTION set_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


-- ---------------------------------------------------------
-- 9. updated_at TRIGGERS (one per table)
-- ---------------------------------------------------------
CREATE TRIGGER customers_set_updated_at
    BEFORE UPDATE ON customers
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER restaurants_set_updated_at
    BEFORE UPDATE ON restaurants
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER riders_set_updated_at
    BEFORE UPDATE ON riders
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER menu_items_set_updated_at
    BEFORE UPDATE ON menu_items
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER orders_set_updated_at
    BEFORE UPDATE ON orders
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TRIGGER order_items_set_updated_at
    BEFORE UPDATE ON order_items
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
